SELECT
hr.value,
hr.create_time
FROM health_record hr
LEFT JOIN health_model hm ON hm.id = hr.health_model_id


        AND hr.user_id = #{userId}


        AND hr.health_model_id = #{healthModelId}


        AND hr.create_time BETWEEN #{startTime} AND #{endTime}


ORDER BY hr.create_time

    LIMIT #{current},#{size}

SELECT hr.id, hr.user_id, hr.health_model_id, hr.value, hr.create_time, u.username, u.avatar, hm.name AS health_model_name, hm.unit AS health_model_unit, hm.normal_value AS normal_value FROM health_record hr LEFT JOIN user u ON u.id = hr.user_id LEFT JOIN health_model hm ON hm.id = hr.health_model_id
AND hr.user_id = #{userId}
AND hr.health_model_id = #{healthModelId}
AND hr.create_time BETWEEN #{startTime} AND #{endTime}
LIMIT #{current},#{size}

SELECT COUNT(*)
FROM health_record hr


        AND hr.user_id = #{userId}


        AND hr.health_model_id = #{healthModelId}


        AND hr.create_time BETWEEN #{startTime} AND #{endTime}
